SELECT e.name,p.oid IS NOT NULL AS present,has_function_privilege('authenticated',p.oid,'EXECUTE') AS authenticated_execute,NOT has_function_privilege('anon',p.oid,'EXECUTE') AS anon_denied,has_function_privilege('service_role',p.oid,'EXECUTE')=e.service AS exact_service_role_access,NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE a.grantee<>p.proowner AND (a.grantee=0 OR pg_get_userbyid(a.grantee) NOT IN ('authenticated','service_role') OR a.is_grantable)) AS no_other_principal,p.prosecdef AS definer FROM (VALUES ('complete_programme_session_and_advance',true),('complete_fixed_programme_occurrence_and_advance',true),('complete_training_session_record',true),('correct_completed_performance_record',false),('complete_backfilled_fixed_programme_occurrence',false)) e(name,service) LEFT JOIN pg_proc p ON p.pronamespace='public'::regnamespace AND p.proname=e.name ORDER BY e.name;
